    macro_rules! ld128 { ($c:expr, $fr:expr, $fm:expr, $a:expr, $dst:expr, $pc:expr, $ic:expr, $rem:expr) => { mmio_ld!($c, $fr, $fm, r128, u128, $a, $dst, $pc, $ic, $rem) }; }
