            // ---- block 0 @0x2758f4 (OFF 0x324): lw v0,0x30(s4); addi s4,s4,0x20; beq s4,s5 -> e0 (slot: lqc2 vf1,0(s4))
            if ic + 84 > lim {
                flush!();
                return deopt(c, fr, fr.pc(0x324), ic);
            }
            let Some(x) = fm.r32((s4 as u32).wrapping_add(0x30)) else {
                flush!();
                return deopt(c, fr, fr.pc(0x324), ic);
            };
            let Some(q) = fm.r128((s4 as u32).wrapping_add(0x20)) else {
                flush!();
                return deopt(c, fr, fr.pc(0x324), ic);
            };
            ic += T[0] as u64;
            v0 = (v0 & HI) | (sx32(x) as u128);
            s4 = sx32((s4 as u32).wrapping_add(0x20));
            let eq = s4 == s5;
            vf1 = V::from_u128(q);
            if eq {
                let _ = go!(c, fr, 0);
                return true;
            }
            let _ = go!(c, fr, 1);
            // ---- block 1 @0x275904 (OFF 0x334): pminw v0,v0,t7; vsub.xyz vf2,vf1,vf24; vaddw.x vf3,vf0,vf1w; dsll32 v0,v0,0;
