            ic += T[1] as u64;
            v0 = mmi::pminw(v0, t7);
            let r2 = vf1.prep().sub(p24);
            stk!(7, r2);
            lv = r2;
            ldest = 0xe;
            any = true;
            v2 = v2.blend::<7>(r2);
            let w1 = vf1.prep().bcw();
            let t3a = p0.add(w1);
            stk!(1, t3a);
            lv = t3a;
            ldest = 0x8;
            v3 = v3.blend::<1>(t3a);
            v0 = (v0 & HI) | (((v0 as u64) << 32) as u128);
            v4 = V::from_u128(v0);
            let z = (v0 as u64) == 0;
            let t3b = p0.sub(w1);
            stk!(2, t3b);
            lv = t3b;
            ldest = 0x4;
            v3 = v3.blend::<2>(t3b);
            if z {
                let _ = go!(c, fr, 2);
                return true;
            }
            let _ = go!(c, fr, 3);
            // ---- block 2 @0x27592c (OFF 0x35c): 40 insns; its sw $zero,0x10(s4) (insn 5) is the only memory op, guarded here first
            if !fm.w32((s4 as u32).wrapping_add(0x10), 0) {
                flush!();
                return deopt(c, fr, fr.pc(0x35c), ic);
            }
