            let p2 = v2.prep();
            let m0 = p25.mul(p2.bcx()); // vmulax.xyz ACC, vf25, vf2x
            acc = acc.blend::<7>(m0);
            stk!(7, m0);
            lv = m0;
            ldest = 0xe;
            let m2 = acc.prep().madd(p26, p2.bcy()); // vmadday.xyz ACC, vf26, vf2y
            acc = acc.blend::<7>(m2);
            stk!(7, m2);
            lv = m2;
            ldest = 0xe;
            s3 = sx32((s3 as u32).wrapping_add(0x40)); // addi s3,s3,0x40
