            stk!(7, m4);
            lv = m4;
            ldest = 0xe;
            let w1b = vf1.prep().bcw();
            let m6 = v4.prep().sub(w1b); // vsubw.y vf19, vf4, vf1w
            v19 = v19.blend::<2>(m6);
            stk!(2, m6);
            lv = m6;
            ldest = 0x4;
            let m8 = p22.mul(w1b); // vmulw.xy vf8, vf22, vf1w
            v8 = v8.blend::<3>(m8);
            stk!(3, m8);
            lv = m8;
            ldest = 0xc;
            let m12 = v3.prep().add(v2.prep().bcz()); // vaddz.xy vf1, vf3, vf2z
            vf1 = vf1.blend::<3>(m12);
            stk!(3, m12);
            lv = m12;
            ldest = 0xc;
            let m14 = p20.mul(v2.prep().bcz()); // vmulz.xy vf5, vf20, vf2z
            v5 = v5.blend::<3>(m14);
            stk!(3, m14);
            lv = m14;
            ldest = 0xc;
            v2 = v2.abs::<3>(); // vabs.xy vf2, vf2
            let m18 = v8.prep().mul(p22.bcz()); // vmulz.xy vf7, vf8, vf22z
            v7 = v7.blend::<3>(m18);
            stk!(3, m18);
            lv = m18;
            ldest = 0xc;
            let m20 = v19.prep().sub(vf1.prep()); // vsub.xy vf3, vf19, vf1
            v3 = v3.blend::<3>(m20);
            stk!(3, m20);
            lv = m20;
            ldest = 0xc;
            let m22 = v5.prep().mul(p21); // vmul.xy vf9, vf5, vf21
            v9 = v9.blend::<3>(m22);
            stk!(3, m22);
            lv = m22;
            ldest = 0xc;
            let m24 = v2.prep().sub(v8.prep()); // vsub.xy vf6, vf2, vf8
            v6 = v6.blend::<3>(m24);
            stk!(3, m24);
            lv = m24;
            ldest = 0xc;
            let m26 = v2.prep().add(v7.prep()); // vadd.xy vf8, vf2, vf7
            v8 = v8.blend::<3>(m26);
            stk!(3, m26);
            lv = m26;
            ldest = 0xc;
            let m28 = vf1.prep().sub(p23); // vsub.xy vf4, vf1, vf23
            v4 = v4.blend::<3>(m28);
            stk!(3, m28);
            lv = m28;
            ldest = 0xc;
            let m30 = vf0r.max(v2); // vmax.z vf1, vf0, vf2 (raw, no flags)
            vf1 = vf1.blend::<4>(m30);
